contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = address(this); }

    // Try calls from this contract (which is the owner of c because c was deployed with this contract as msg.sender)
    // and also simulate a non-owner by using a low-level call from a different address via call{value: ...} not possible here,
    // so we instead check that when called by owner the calls succeed and change balances accordingly, and when made
    // with invalid parameters that would attempt to withdraw more than balance they revert and do not mutate counts.

    // The test takes parameters to exercise withdraw, withdrawAll, sendMoney and fallback deposits.
    function run(address payable target, uint depositAmount, uint withdrawAmount, uint sendAmount) public payable {
        require(true);
        // Ensure this test contract has enough balance to send depositAmount and sendAmount
        require(address(this).balance >= depositAmount + sendAmount, "insufficient funds for test");

        // Record before values
        uint beforeDepositsCount = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // 1) Send Ether to c via fallback to increment depositsCount
        // Use call to trigger fallback: c is external, so we use payable call on address(c)
        (bool sent1, ) = address(c).call{value: depositAmount}("");
        // fallback increments depositsCount on success

        // Read intermediate values
        uint midDepositsCount = c.depositsCount();
        uint midBalance = address(c).balance;

        // 2) Owner (this contract) attempts to withdraw withdrawAmount. This should succeed iff withdrawAmount <= midBalance
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // 3) Reset: attempt to send sendAmount from c to target via sendMoney (owner call). It should revert if c has insufficient balance.
        bool sendReverted;
        try c.sendMoney(target, sendAmount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        uint finalBalance = address(c).balance;
        uint finalDepositsCount = c.depositsCount();

        // General rule asserted:
        // - The depositsCount increases by exactly 1 if and only if the initial call to fallback succeeded (i.e., midBalance == beforeBalance + depositAmount and midDepositsCount == beforeDepositsCount + 1).
        // - A withdraw call only succeeds (did not revert) when the requested amount was <= the contract balance at the time; if it reverts then balance is unchanged by that withdraw attempt.
        // - Similarly sendMoney only succeeds when sendAmount <= balance at that time; if it reverts then balance is unchanged by that send attempt.
        assert(
            // depositsCount change matches balance increase caused by fallback
            ((midDepositsCount == beforeDepositsCount + 1) == (midBalance == beforeBalance + depositAmount))
            // If withdraw did not revert, then c's balance decreased by withdrawAmount (or to zero if withdrawAmount > midBalance but that would have reverted)
            && (withdrewReverted ? (afterBalance == midBalance) : (afterBalance + withdrawAmount == midBalance))
            // If sendMoney did not revert, then finalBalance decreased by sendAmount from afterBalance; otherwise unchanged
            && (sendReverted ? (finalBalance == afterBalance) : (finalBalance + sendAmount == afterBalance))
            // depositsCount never decreases and only possibly increased by the fallback call
            && (finalDepositsCount >= beforeDepositsCount) && (finalDepositsCount == midDepositsCount)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry that performs all interactions and ends with one assert
    function run(address payable target, uint depositAmount, uint withdrawAmount, uint sendAmount) public payable {
        require(address(this).balance >= depositAmount + sendAmount, "insufficient funds for test");

        // Observe initial state
        uint beforeDepositsCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // 1) Trigger fallback by sending Ether to c
        (bool sentDeposit, ) = address(c).call{value: depositAmount}("");

        // Read state after deposit attempt
        uint midDepositsCount = c.depositsCount();
        uint midBalance = address(c).balance;

        // 2) Owner (this contract) attempts to withdraw withdrawAmount
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDepositsCount = c.depositsCount();

        // 3) Owner (this contract) attempts to send sendAmount to target via sendMoney
        bool sendReverted;
        try c.sendMoney(target, sendAmount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        uint finalBalance = address(c).balance;
        uint finalDepositsCount = c.depositsCount();

        // General rule asserted as one condition:
        // - If the external call that sent depositAmount succeeded, then depositsCount increased by exactly 1 and balance increased by depositAmount.
        //   Otherwise depositsCount and balance unchanged by that deposit attempt.
        // - A withdraw call that reverted does not change the contract balance; if it succeeded it reduced the balance by exactly withdrawAmount.
        // - A sendMoney call that reverted does not change the contract balance; if it succeeded it reduced the balance by exactly sendAmount.
        assert(
            // deposit effect correlates with call success
            ((sentDeposit && midDepositsCount == beforeDepositsCount + 1 && midBalance == beforeBalance + depositAmount)
             || (!sentDeposit && midDepositsCount == beforeDepositsCount && midBalance == beforeBalance))
            // withdraw effect: either reverted and no change, or succeeded and decreased by withdrawAmount
            && (withdrewReverted ? (afterBalance == midBalance) : (afterBalance + withdrawAmount == midBalance))
            // withdraw does not affect depositsCount
            && (afterDepositsCount == midDepositsCount)
            // sendMoney effect: either reverted and no change, or succeeded and decreased by sendAmount
            && (sendReverted ? (finalBalance == afterBalance) : (finalBalance + sendAmount == afterBalance))
            // sendMoney does not affect depositsCount
            && (finalDepositsCount == afterDepositsCount)
        );
    }

    receive() external payable { }
}

