contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that if this contract (which is NOT the owner of C) tries to call
    // withdraw, withdrawAll, or sendMoney, those calls revert and do not change observable state.
    // Inputs:
    //   initialFunding: amount of wei to send into c via fallback to increment depositsCount
    //   sendAmount: amount to attempt to withdraw/send from c (must be <= address(c).balance to be meaningful)
    function run(uint initialFunding, uint sendAmount) public payable {
        // ensure we have funds to push into c for its balance
        require(address(this).balance >= initialFunding, "insufficient test balance");

        // 1) send some ether into c to change its balance and trigger fallback (++depositsCount)
        uint beforeDeposits = c.depositsCount();
        // perform external call sending Ether to c which will invoke fallback and increment depositsCount
        c.f{value: initialFunding}();
        uint afterDeposits = c.depositsCount();

        // Observe balance of c after funding
        uint balanceAfterFund = address(c).balance;

        // Cap sendAmount to balanceAfterFund to avoid unintentionally testing logic unrelated to ownership
        if (sendAmount > balanceAfterFund) {
            sendAmount = balanceAfterFund;
        }

        // Try withdrawAll (should revert because msg.sender != owner)
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Try withdraw(sendAmount)
        bool revertedWithdraw;
        try c.withdraw(sendAmount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Try sendMoney to this contract
        bool revertedSendMoney;
        try c.sendMoney(address(this), sendAmount) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }

        // Read observables after the attempted calls
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;
        uint ourBalance = address(this).balance;

        // General rule (assert): Because this contract is not the owner of c, all three owner-only operations
        // must revert, and as a consequence depositsCount and c's balance must remain unchanged by them.
        // We also assert that the initial funding did increment depositsCount by either 0 or 1 (fallback ran if funding>0).
        assert(
            // funding caused at most one increment
            (afterDeposits == beforeDeposits || afterDeposits == beforeDeposits + 1)
            // all owner-only calls reverted
            && revertedWithdrawAll && revertedWithdraw && revertedSendMoney
            // no observable change to depositsCount or c balance after the revert attempts
            && finalDeposits == afterDeposits
            && finalBalance == balanceAfterFund
        );
    }

    // Allow receiving Ether when c tries to send to this contract (should not happen for non-owner sends)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test parameters:
    // initialFunding: amount of wei to send into c (triggers fallback if >0)
    // sendAmount: amount to attempt to withdraw/send from c (will be capped to c's balance)
    function run(uint initialFunding, uint sendAmount) public payable {
        // ensure this test contract has enough balance to fund c
        require(address(this).balance >= initialFunding, "insufficient test balance");

        // Observe depositsCount before funding
        uint beforeDeposits = c.depositsCount();

        // Send Ether to c to trigger fallback (use low-level call to invoke fallback)
        (bool sent, ) = address(c).call{value: initialFunding}("{}");
        require(sent, "funding call failed");

        // Observe depositsCount and balance after funding
        uint afterDeposits = c.depositsCount();
        uint balanceAfterFund = address(c).balance;

        // Cap sendAmount to current balance to avoid meaningless oversized attempts
        if (sendAmount > balanceAfterFund) {
            sendAmount = balanceAfterFund;
        }

        // Try withdrawAll (should revert because this contract is NOT the owner)
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Try withdraw(sendAmount)
        bool revertedWithdraw;
        try c.withdraw(sendAmount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Try sendMoney to this contract
        bool revertedSendMoney;
        try c.sendMoney(address(this), sendAmount) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }

        // Read observables after the attempted calls
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule (single assert):
        // - The initial funding via fallback increments depositsCount by at most 1.
        // - Since this contract is not the owner of c, all owner-only operations must revert.
        // - Those reverted calls must not change depositsCount or c's balance.
        assert(
            (afterDeposits == beforeDeposits || afterDeposits == beforeDeposits + 1)
            && revertedWithdrawAll && revertedWithdraw && revertedSendMoney
            && finalDeposits == afterDeposits
            && finalBalance == balanceAfterFund
        );
    }

    // Allow receiving Ether in case c.sendMoney would succeed (it should not in this test)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // fund: amount this test contract will send to c to trigger fallback
    // attempt: amount to attempt withdraw/sendMoney (capped to c balance)
    function run(uint fund, uint attempt) public payable {
        require(address(this).balance >= fund, "insufficient balance to fund c");

        // observe depositsCount before
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send Ether to c to trigger fallback (must be a plain top-level call)
        (bool ok, ) = address(c).call{value: fund}("");
        require(ok, "funding call failed");

        // observe after funding
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // cap attempt to current c balance to keep withdraw/sendMoney meaningful
        uint cap = afterBalance < attempt ? afterBalance : attempt;

        // try withdrawAll (should revert because this contract is not owner)
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // try withdraw(cap)
        bool revertedWithdraw;
        try c.withdraw(cap) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // try sendMoney to this contract
        bool revertedSendMoney;
        try c.sendMoney(address(this), cap) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }

        // observe final state
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule asserted:
        // - The fallback caused by sending `fund` increments depositsCount by exactly 1.
        // - Because this contract is NOT the owner (the owner is C's deployer), owner-only functions invoked above must revert.
        // - Those reverted owner-only attempts must not change c's balance.
        assert(
            afterDeposits == beforeDeposits + 1
            && revertedWithdrawAll && revertedWithdraw && revertedSendMoney
            && finalDeposits == afterDeposits
            && finalBalance == afterBalance
        );
    }

    // allow receiving Ether if sendMoney ever succeeds (should not for non-owner)
    receive() external payable {}
}

