contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test exercises withdraw, withdrawAll, sendMoney, and fallback via sending Ether.
    // Parameters:
    // - amountDeposit: amount of wei to send to c via plain call triggering fallback (increasing depositsCount)
    // - withdrawAmount: amount to withdraw via withdraw(uint)
    // - sendAmount: amount to send via sendMoney to target (we'll use address(this) as target)
    function run(uint amountDeposit, uint withdrawAmount, uint sendAmount) public payable {
        require(address(this).balance >= amountDeposit + sendAmount, "insufficient balance for test");

        // Read initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // 1) Send Ether with plain call to trigger fallback (increments depositsCount)
        // Use low-level call to c from this contract: this will forward value and trigger fallback()
        (bool okDeposit, ) = address(c).call{value: amountDeposit}("");
        // okDeposit indicates whether the fallback call succeeded

        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

