    // We observe whether they revert and check balances and depositsCount observable state.
    function run(address payable target, uint value, uint sendAmount) public payable {
        // Preconditions for sending Ether to c: ensure this contract has enough balance
        require(address(this).balance >= sendAmount);

        // Record observable state before actions
        uint before_c_balance = address(c).balance;
        uint before_deposits = c.depositsCount();

        // First, fund c by calling its fallback via a plain call with Ether (fallback increments depositsCount)
        // Use the provided sendAmount parameter to transfer Ether into c
        c.f{value: sendAmount}();

        // Check observed effect of funding: c.balance increases by sendAmount and depositsCount increments by 1
        uint after_fund_c_balance = address(c).balance;
        uint after_fund_deposits = c.depositsCount();

        // Now attempt three owner-only actions from this contract (which is NOT owner): withdraw, withdrawAll, sendMoney
        // We capture whether they revert. According to the contract, they should revert because onlyOwner modifier checks msg.sender==owner
        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, value) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Observe final state
        uint final_c_balance = address(c).balance;
        uint final_deposits = c.depositsCount();
        uint my_balance = address(this).balance;

        // General rule asserted:
        // 1) Funding via fallback must have increased c.balance by sendAmount and depositsCount by 1.
        // 2) If any of the owner-only calls did NOT revert (i.e., succeeded), then this contract must have been paid exactly the amount withdrawn and c.balance must have decreased accordingly.
        // 3) If they reverted, they must not have changed c.balance or depositsCount.
        // We express this as one combined assert using only observable values and revert flags.
        assert(
            // funding effect holds
            after_fund_c_balance == before_c_balance + sendAmount
            && after_fund_deposits == before_deposits + 1
            // If withdraw succeeded, c.balance decreased by value and this contract's balance increased by value
            && (withdrewReverted || (final_c_balance == after_fund_c_balance - value && my_balance >= address(this).balance))
            // If withdrawAll succeeded, final_c_balance should be zero (since withdrawAll withdraws all) and my balance increased accordingly
            && (withdrawAllReverted || final_c_balance == 0)
            // If sendMoney succeeded, then c.balance decreased by value (or by sum of successful transfers) — ensure not negative
            && (sendMoneyReverted || after_fund_c_balance >= value)
            // Reverting calls did not change depositsCount
            && (withdrewReverted ? final_deposits == after_fund_deposits : true)
            && (withdrawAllReverted ? final_deposits == after_fund_deposits : true)
            && (sendMoneyReverted ? final_deposits == after_fund_deposits : true)
        );
    }

    receive() external payable {}
}

