        // balance must be <= afterFundBalance (it withdraws funds). If the caller is not owner,
        // withdrawAll must revert and final balance must equal afterFundBalance (no funds moved).
        assert(
            (asOwner && !reverted && finalBalance <= afterFundBalance)
            || (!asOwner && reverted && finalBalance == afterFundBalance)
        );
    }

