contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters to attempt operations as arbitrary targets and amounts.
    // This single public function performs calls on c and asserts a general invariant
    // about owner-only access: if a call by this contract (which is NOT the owner) to
    // withdraw/withdrawAll/sendMoney does not revert, then msg.sender of C must be the owner
    // (i.e., the deployer of C). Since the checker deploys a fresh C with owner = deployer (not this contract),
    // calls from this contract should revert; we assert that any non-reverting call cannot change balance
    // or depositsCount unexpectedly.
    function run(address payable target, uint amount, uint fallbackValue) public payable {
        require(true);

        // Read observables before
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Try triggering fallback by sending Ether to c from this contract
        if (fallbackValue > 0) {
            // ensure test contract has enough balance to send
            require(address(this).balance >= fallbackValue);
            // This will invoke C.fallback and increment depositsCount on success
            (bool sent,) = address(c).call{value: fallbackValue}("");
            // sent may be true or false; depositsCount observable will reflect change only if sent
        }

        // Attempt withdrawAll and record whether it reverts
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Attempt withdraw(amount) and record whether it reverts
        bool withdrawReverted;
        try c.withdraw(amount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Attempt sendMoney to provided target
        bool sendMoneyReverted;
        try c.sendMoney(target, amount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read observables after
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // If any of the owner-only actions (withdrawAll, withdraw, sendMoney) did NOT revert when invoked
        // by this contract, then the contract balance must have decreased by at most the sum of successful
        // non-reverting transfers and depositsCount may only have increased due to a successful fallback call.
        // Concretely: any non-reverting owner-only call implies the balance did not increase (so afterBalance <= beforeBalance + fallback increase)
        // and depositsCount did not decrease. We express this safely without underflow.
        bool anyOwnerCallSucceeded = (!withdrawAllReverted) || (!withdrawReverted) || (!sendMoneyReverted);

        // Compute minimal allowed afterBalance considering fallbackValue succeeded or not.
        // afterDeposits >= beforeDeposits always should hold (fallback increments only). So require that.
        assert(afterDeposits >= beforeDeposits);

        // If any owner-only call succeeded, the contract must not have gained net Ether beyond what we explicitly sent via fallback.
        // That means afterBalance <= beforeBalance + (afterDeposits - beforeDeposits) * fallbackValue
        // But fallbackValue could have been partially or fully not sent; to remain general, we allow any increase up to fallbackValue if we attempted it once.
        uint maxAllowedIncrease = beforeBalance;
        if (afterDeposits > beforeDeposits) {
            // We sent fallbackValue once at most in this test
            // so allow balance to be beforeBalance + fallbackValue
            maxAllowedIncrease = beforeBalance + fallbackValue;
        }

        assert(!(anyOwnerCallSucceeded) || (afterBalance <= maxAllowedIncrease));
    }

    // Allow this test contract to receive Ether so it can forward in run
    receive() external payable { }
}

