    // Attempt to prove: if caller of withdraw is not owner, the call reverts and balance unchanged.
    // We take target (recipient) and value to attempt to withdraw; we also can send some ether to c via fallback by calling c with value.
    // The InvMutTest contract is the owner of c (because it deployed c in the harness), so to simulate non-owner we call via a proxy: we use call to c from a different address is not possible here.
    // Instead, we check the general rule for sendMoney: sendMoney requires onlyOwner, so non-owner cannot call it — we simulate a non-owner by using a low-level call from this contract but with a modified msg.sender isn't possible.
    // To produce a meaningful property reachable in this single-contract setting, we assert that if this contract (the owner) calls withdraw to send funds to itself, then address(this).balance increases by that amount; and that withdraw reverts if trying to withdraw more than address(c).balance.

    // Public test function: parameters amountToFund and withdrawAmount
    function run(uint amountToFund, uint withdrawAmount, address payable recipient) public payable {
        require(address(this).balance >= amountToFund, "insufficient balance to fund C");

        // Fund c by sending Ether to its fallback which increments depositsCount
        c.f{value: amountToFund}();

        // Record balances before withdraw
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeDepositsCount = c.depositsCount();

        bool didRevert;
        // Try withdraw the requested amount as owner (this contract is owner)
        try c.withdraw(withdrawAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterDepositsCount = c.depositsCount();

        // General rule asserted:
        // - depositsCount increments exactly once because we sent to fallback above.
        // - If withdraw did not revert, then either withdrawAmount <= beforeC and this contract's balance increased by withdrawAmount and c's balance decreased by withdrawAmount.
        // - If withdraw reverted, then withdrawAmount > beforeC and balances unchanged.
        assert(
            afterDepositsCount == beforeDepositsCount + 1 &&
            (
                (!didRevert && beforeC >= withdrawAmount && afterC + withdrawAmount == beforeC && afterThis == beforeThis + withdrawAmount)
                ||
                (didRevert && afterC == beforeC && afterThis == beforeThis)
            )
        );
    }

    receive() external payable {}
