        uint balAfter = address(c).balance;
        uint depAfter = c.depositsCount();

        // General rule: if the low-level call reverted, no changes; otherwise balance increases by amount and depositsCount by 1
        assert(reverted ? (balAfter == balBefore && depAfter == depBefore) : (balAfter == balBefore + amount && depAfter == depBefore + 1));
